package gstack

import "testing"

func TestPushPop(t *testing.T) {
	var s Stack[int]
	s.Push(1)
	s.Push(2)
	s.Push(3)
	v, ok := s.Pop()
	if !ok || v != 3 {
		t.Fatalf("want 3 true, got %v %v", v, ok)
	}
}

func TestPeek(t *testing.T) {
	var s Stack[string]
	s.Push("hello")
	v, ok := s.Peek()
	if !ok || v != "hello" {
		t.Fatalf("want hello true, got %v %v", v, ok)
	}
	if s.Len() != 1 {
		t.Fatalf("Peek should not remove element, len=%d", s.Len())
	}
}

func TestIsEmpty(t *testing.T) {
	var s Stack[float64]
	if !s.IsEmpty() {
		t.Fatal("new stack should be empty")
	}
	s.Push(1.0)
	if s.IsEmpty() {
		t.Fatal("non-empty stack should not be empty")
	}
}

func TestPopEmpty(t *testing.T) {
	var s Stack[int]
	_, ok := s.Pop()
	if ok {
		t.Fatal("Pop on empty stack should return false")
	}
}

func TestLen(t *testing.T) {
	var s Stack[int]
	for i := 0; i < 5; i++ {
		s.Push(i)
	}
	if s.Len() != 5 {
		t.Fatalf("want 5, got %d", s.Len())
	}
}

